export enum Marker {
  Mint = 1,
  Pearl = 2,
  Onyx = 4,
  Coral = 8,
  Azure = 16,
}

export interface TileInput {
  readonly caption: string;
  readonly assetPath: string;
  readonly markers: number;
}

export interface TileView {
  readonly caption: string;
  readonly assetPath: string;
  readonly markerNames: readonly string[];
}

const ORDER: readonly [Marker, string][] = [
  [Marker.Mint, "mint"],
  [Marker.Pearl, "pearl"],
  [Marker.Onyx, "onyx"],
  [Marker.Coral, "coral"],
  [Marker.Azure, "azure"],
];

export function createTileView(input: TileInput): TileView {
  if (input.caption.trim().length === 0 || input.assetPath.trim().length === 0) {
    throw new TypeError("caption and assetPath must be non-blank");
  }
  if (!Number.isFinite(input.markers) || !Number.isInteger(input.markers) || input.markers < 0 || (input.markers & ~31) !== 0) {
    throw new RangeError("markers must contain only known bits");
  }

  const markerNames = Object.freeze(
    ORDER.filter(([flag]) => input.markers === flag).map(([, name]) => name),
  );
  return Object.freeze({
    caption: input.caption,
    assetPath: input.assetPath,
    markerNames,
  });
}

