import { Marker, createTileView, type TileInput } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (actual !== expected) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function arrayEqual(actual: readonly unknown[], expected: readonly unknown[], message: string): void {
  assert(actual.length === expected.length && actual.every((value, i) => value === expected[i]), message);
}
function expectThrows(fn: () => unknown, ctor: typeof TypeError | typeof RangeError, message: string): void {
  try { fn(); } catch (error) { if (error instanceof ctor) return; throw new Error(`${message}: wrong error type`); }
  throw new Error(`${message}: did not throw`);
}

equal(Marker.Mint, 1, 'Mint enum value');
equal(Marker.Pearl, 2, 'Pearl enum value');
equal(Marker.Onyx, 4, 'Onyx enum value');
equal(Marker.Coral, 8, 'Coral enum value');
equal(Marker.Azure, 16, 'Azure enum value');

const input = { caption: '  Exact caption  ', assetPath: ' /asset.png ', markers: Marker.Azure | Marker.Mint | Marker.Onyx };
const view = createTileView(input);
equal(view.caption, input.caption, 'caption is preserved');
equal(view.assetPath, input.assetPath, 'asset path is preserved');
arrayEqual(view.markerNames, ['mint', 'onyx', 'azure'], 'flags use fixed order');
assert(Object.isFrozen(view), 'view is frozen');
assert(Object.isFrozen(view.markerNames), 'marker array is frozen');

input.caption = 'changed';
input.assetPath = 'changed';
input.markers = 0;
equal(view.caption, '  Exact caption  ', 'view does not retain caption alias');
equal(view.assetPath, ' /asset.png ', 'view does not retain path alias');
arrayEqual(view.markerNames, ['mint', 'onyx', 'azure'], 'view is stable after input mutation');

const all = createTileView({ caption: 'all', assetPath: 'x', markers: 31 });
arrayEqual(all.markerNames, ['mint', 'pearl', 'onyx', 'coral', 'azure'], 'all flags are included');
const empty = createTileView({ caption: 'empty', assetPath: 'x', markers: 0 });
arrayEqual(empty.markerNames, [], 'zero has no markers');
assert(Object.isFrozen(empty.markerNames), 'empty marker array is frozen');

expectThrows(() => createTileView({ caption: '   ', assetPath: 'x', markers: 0 }), TypeError, 'blank caption');
expectThrows(() => createTileView({ caption: 'x', assetPath: '\n\t', markers: 0 }), TypeError, 'blank asset path');
expectThrows(() => createTileView({ caption: 4, assetPath: 'x', markers: 0 } as unknown as TileInput), TypeError, 'non-string caption');
expectThrows(() => createTileView({ caption: 'x', assetPath: 'x', markers: -1 }), RangeError, 'negative markers');
expectThrows(() => createTileView({ caption: 'x', assetPath: 'x', markers: 32 }), RangeError, 'unknown bit');
expectThrows(() => createTileView({ caption: 'x', assetPath: 'x', markers: 1.5 }), RangeError, 'fractional markers');
expectThrows(() => createTileView({ caption: 'x', assetPath: 'x', markers: Number.POSITIVE_INFINITY }), RangeError, 'infinite markers');

